import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    n, x = int(data[0]), int(data[1])
    a = [int(v) for v in data[2:2 + n]]
    dq = deque()
    best = None
    for i in range(n):
        while dq and a[dq[-1]] >= a[i]:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - x:
            dq.popleft()
        if i >= x - 1:
            m = a[dq[0]]
            if best is None or m > best:
                best = m
    print(best)

